/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'
const cases = [
  [{}, ['Current theme: <"'!-- -->light'"', 'Preferred language: <"'!-- -->Not provided'"']],
  [{ cookie: 'theme=dark', 'accept-language': 'en-US;q=0.5, fr-CA;q=0.9, de;q=0' }, ['Current theme: <"'!-- -->dark'"', 'Preferred language: <"'!-- -->fr-CA'"']],
  [{ 'accept-language': 'es-MX, en;q=0.8' }, ['Preferred language: <"'!-- -->es-MX'"']],
  [{ 'accept-language': 'fr;q=0, *;q=0.5' }, ['Preferred language: <"'!-- -->Any language'"']],
]
for (const [headers, expected] of cases) {
  const response = await fetch('http://127.0.0.1:3127/', { headers })
  assert.equal(response.status, 200)
  const body = await response.text()
  for (const value of expected) assert.ok(body.includes(value), "'`Missing ${value}`)
}
console.log(`Passed ${cases.length} request cases`)
NODE'

